import React from 'react';
import { Link, NavLink, useNavigate } from 'react-router-dom';
import { api } from '../services/api';

export default function Navbar() {
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem('user') || 'null');

  async function handleLogout() {
    try {
      await api.post('/logout.php');
    } catch (e) {
      console.error('Logout error:', e);
    } finally {
      localStorage.removeItem('user');
      navigate('/');
    }
  }

  return (
    <header className="bg-white border-b shadow-sm sticky top-0 z-50">
      <div className="container mx-auto px-4 py-4 flex items-center justify-between">
        <Link to="/home" className="flex items-center gap-2.5 hover:opacity-80 transition-opacity group">
          <div className="h-10 w-10 bg-gradient-to-br from-indigo-600 to-purple-600 rounded-lg flex items-center justify-center shadow-md group-hover:shadow-lg transition-shadow">
            <span className="text-white font-bold text-lg">EV</span>
          </div>
          <span className="text-2xl font-bold bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">EduVault</span>
        </Link>
        <nav className="flex items-center gap-1">
          <NavLink 
            to="/home" 
            end 
            className={({isActive}) => 
              `px-4 py-2 text-sm font-medium rounded-lg transition-all duration-200 ${
                isActive 
                  ? 'text-indigo-600 bg-indigo-50' 
                  : 'text-gray-700 hover:text-indigo-600 hover:bg-gray-50'
              }`
            }
          >
            Home
          </NavLink>
          <NavLink 
            to="/upload" 
            className={({isActive}) => 
              `px-4 py-2 text-sm font-medium rounded-lg transition-all duration-200 ${
                isActive 
                  ? 'text-indigo-600 bg-indigo-50' 
                  : 'text-gray-700 hover:text-indigo-600 hover:bg-gray-50'
              }`
            }
          >
            Upload
          </NavLink>
          {user && (
            <div className="flex items-center gap-3 ml-4 pl-4 border-l border-gray-200">
              <div className="flex items-center gap-2">
                <div className="h-8 w-8 bg-gradient-to-br from-indigo-500 to-purple-500 rounded-full flex items-center justify-center text-white font-semibold text-sm">
                  {user.name.charAt(0).toUpperCase()}
                </div>
                <div className="flex flex-col">
                  <span className="text-xs text-gray-500">Welcome back,</span>
                  <span className="text-sm font-semibold text-gray-900">{user.name}</span>
                </div>
              </div>
              {user.role === 'admin' && (
                <span className="px-2.5 py-1 text-xs bg-purple-100 text-purple-700 rounded-full font-semibold border border-purple-200">
                  Admin
                </span>
              )}
              <button
                onClick={handleLogout}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors flex items-center gap-2"
              >
                <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                </svg>
                Logout
              </button>
            </div>
          )}
        </nav>
      </div>
    </header>
  );
}
